# reuse grid from previous parse, find 4-connected color-2 components and line intersections
from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==2 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     p=(x+dx,y+dy)
     if 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]]==2 and p not in seen: seen.add(p);q.append(p)
   comps.append(comp)
[(len(co),(min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co)), any(r in (4,11) or c==5 for r,c in co)) for co in comps]

# Compare 8-connected components and their bounding boxes to marker lines
seen8=set(); co8=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==2 and (r,c) not in seen8:
   q=[(r,c)];seen8.add((r,c));cc=[]
   while q:
    x,y=q.pop();cc.append((x,y))
    for dx in (-1,0,1):
     for dy in (-1,0,1):
      p=(x+dx,y+dy)
      if (dx or dy) and 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]]==2 and p not in seen8: seen8.add(p);q.append(p)
   co8.append(cc)
[(len(cc),(min(r for r,c in cc),max(r for r,c in cc),min(c for r,c in cc),max(c for r,c in cc)),any(r in (4,11) or c==5 for r,c in cc)) for cc in co8]
